import { MakeLogicType, actions, kea, path, reducers } from 'kea'

import { DateRange } from '~/queries/schema/schema-general'

export const HOME_TAB_DEFAULT_DATE_RANGE: DateRange = { date_from: '-30d', date_to: null }

export type HomeTabMetricKey = 'active_users' | 'sessions' | 'new_users' | 'session_duration' | 'daily_active_users'
export type HomeTabContentKey = 'top_pages' | 'top_screens'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface homeTabDefaultLogicValues {
    compare: boolean
    dateRange: DateRange
    selectedContentKey: HomeTabContentKey
    selectedMetric: HomeTabMetricKey
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface homeTabDefaultLogicActions {
    setCompare: (compare: boolean) => {
        compare: boolean
    }
    setDates: (
        dateFrom: string | null,
        dateTo: string | null,
        explicitDate?: boolean
    ) => {
        dateFrom: string | null
        dateTo: string | null
        explicitDate: boolean | undefined
    }
    setSelectedContentKey: (key: HomeTabContentKey) => {
        key: HomeTabContentKey
    }
    setSelectedMetric: (key: HomeTabMetricKey) => {
        key: HomeTabMetricKey
    }
}

export type homeTabDefaultLogicType = MakeLogicType<homeTabDefaultLogicValues, homeTabDefaultLogicActions>

export const homeTabDefaultLogic = kea<homeTabDefaultLogicType>([
    path(['scenes', 'saved-insights', 'homeTabDefaultLogic']),
    actions({
        setDates: (dateFrom: string | null, dateTo: string | null, explicitDate?: boolean) => ({
            dateFrom,
            dateTo,
            explicitDate,
        }),
        setCompare: (compare: boolean) => ({ compare }),
        setSelectedContentKey: (key: HomeTabContentKey) => ({ key }),
        setSelectedMetric: (key: HomeTabMetricKey) => ({ key }),
    }),
    reducers({
        dateRange: [
            HOME_TAB_DEFAULT_DATE_RANGE,
            {
                setDates: (_, { dateFrom, dateTo, explicitDate }) => ({
                    date_from: dateFrom ?? '-30d',
                    date_to: dateTo,
                    explicitDate,
                }),
            },
        ],
        compare: [true, { setCompare: (_, { compare }) => compare }],
        selectedContentKey: ['top_pages' as HomeTabContentKey, { setSelectedContentKey: (_, { key }) => key }],
        selectedMetric: ['active_users' as HomeTabMetricKey, { setSelectedMetric: (_, { key }) => key }],
    }),
])
